  return root.findAll(n=>n.type==='TEXT' && n.characters && n.characters.trim().toLowerCase()===txt.toLowerCase());
}
function findButton(root,label){
  const bs=root.findAll(n=>n.type==='INSTANCE' && n.mainComponent && n.mainComponent.id==='1:24');
  return bs.filter(b=>{const t=b.findOne(n=>n.type==='TEXT');return t && t.characters && t.characters.trim().toLowerCase()===label.toLowerCase();});
}
