const ws=await figma.getNodeByIdAsync('8:2');
const out={};
for(const f of ws.children.filter(n=>n.type==='FRAME'&&/^\d\d_/.test(n.name))){
  const rs=f.findAll(n=>n.reactions && n.reactions.length>0);
  out[f.name]=rs.map(n=>{
    let label=null;
    if(n.type==='TEXT') label=n.characters;
    else { const t=n.findOne(x=>x.type==='TEXT'); label=t?t.characters:null; }
    return {t:n.type,label,to:n.reactions[0].actions[0]?n.reactions[0].actions[0].destinationId:null};
  });
}
return out;

